Plan: Give all increments the same mutex, join the workers, then check the total.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
static void ck(int e) { if (e) { fprintf(stderr, "pthread error %d\n", e); exit(1); } }
enum { N=2, R=20 };
static int count;
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static void *worker(void *arg) {
    (void)arg;
    for (int i=0; i<R; ++i) {
        ck(pthread_mutex_lock(&m)); /* entry section */
        ++count;                  /* critical section */
        ck(pthread_mutex_unlock(&m)); /* exit section */
    }
    return NULL;
}
int main(void) {
    pthread_t t[N];
    for (int i=0; i<N; ++i) ck(pthread_create(&t[i],NULL,worker,NULL));
    for (int i=0; i<N; ++i) ck(pthread_join(t[i],NULL));
    assert(count==N*R);
    printf("count=%d\n",count);
    ck(pthread_mutex_destroy(&m));
    return 0;
}
```

Why it is correct: The same mutex serializes every read-modify-write. Its entry and exit sections surround the complete critical section; joins precede the final read.

