Plan: Reserve one permit per job and separately lock the statistics.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
static void ck(int e) { if (e) { fprintf(stderr, "pthread error %d\n", e); exit(1); } }
/* Semaphore wait/signal (P/V) map to sem_wait/sem_post. */
static void P(sem_t *s) {
    while (sem_wait(s) == -1) { if (errno != EINTR) abort(); }
}
static void V(sem_t *s) { if (sem_post(s) == -1) abort(); }
static void init(sem_t *s, unsigned n) { if (sem_init(s, 0, n)) abort(); }
static void drop(sem_t *s) { if (sem_destroy(s)) abort(); }
enum { N=3, CAP=1 };
static sem_t slots;
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static int active, peak, completed;
static void *worker(void *arg) {
    (void)arg;
    P(&slots); /* entry: reserve a permit */
    ck(pthread_mutex_lock(&m));
    ++active;
    if (active>peak) peak=active;
    assert(active<=CAP);
    ck(pthread_mutex_unlock(&m));
    /* finite work; active is protected separately from the permit count */
    ck(pthread_mutex_lock(&m));
    --active; ++completed;
    ck(pthread_mutex_unlock(&m));
    V(&slots); /* exit: return the permit */
    return NULL;
}
int main(void) {
    pthread_t t[N]; init(&slots,CAP);
    for (int i=0; i<N; ++i) ck(pthread_create(&t[i],NULL,worker,NULL));
    for (int i=0; i<N; ++i) ck(pthread_join(t[i],NULL));
    assert(completed==N && active==0 && peak<=CAP);
    printf("completed=%d capacity=%d\n",completed,CAP);
    drop(&slots); ck(pthread_mutex_destroy(&m)); return 0;
}
```

Why it is correct: At most CAP successful unreleased P operations exist. The statistics critical section uses a mutex because a capacity semaphore with several permits is not mutual exclusion.

