Plan: Both workers lock account 0 then account 1, regardless of transfer direction.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
static void ck(int e) { if (e) { fprintf(stderr, "pthread error %d\n", e); exit(1); } }
enum { R=20, INITIAL=100 };
static int balance[2]={INITIAL,INITIAL},ids[2]={0,1};
static pthread_mutex_t m[2]={PTHREAD_MUTEX_INITIALIZER,PTHREAD_MUTEX_INITIALIZER};
static void *worker(void *arg) {
    int from=*(int *)arg,to=1-from;
    for (int i=0; i<R; ++i) {
        ck(pthread_mutex_lock(&m[0])); ck(pthread_mutex_lock(&m[1]));
        if (balance[from]>0) { --balance[from]; ++balance[to]; }
        assert(balance[0]+balance[1]==2*INITIAL);
        ck(pthread_mutex_unlock(&m[1])); ck(pthread_mutex_unlock(&m[0]));
    } return NULL;
}
int main(void) {
    pthread_t t[2];
    for (int i=0; i<2; ++i) ck(pthread_create(&t[i],NULL,worker,&ids[i]));
    for (int i=0; i<2; ++i) ck(pthread_join(t[i],NULL));
    assert(balance[0]>=0 && balance[1]>=0 && balance[0]+balance[1]==2*INITIAL);
    printf("total=%d\n",balance[0]+balance[1]);
    for (int i=0; i<2; ++i) ck(pthread_mutex_destroy(&m[i]));
    return 0;
}
```

Why it is correct: A global acquisition order removes circular wait. The full check/debit/credit is one critical section, preserving nonnegative balances and the combined total.

