Plan: Acquire the atomic flag before the increment and clear it with release afterward.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
static void ck(int e) { if (e) { fprintf(stderr, "pthread error %d\n", e); exit(1); } }
enum { N=2, R=20 };
static atomic_flag gate=ATOMIC_FLAG_INIT;
static int count;
static void *worker(void *arg) {
    (void)arg;
    for (int k=0; k<R; ++k) {
        while (atomic_flag_test_and_set_explicit(&gate,memory_order_acquire)) {}
        ++count; /* critical section */
        atomic_flag_clear_explicit(&gate,memory_order_release); /* exit section */
    } return NULL;
}
int main(void) {
    pthread_t t[N];
    for (int i=0; i<N; ++i) ck(pthread_create(&t[i],NULL,worker,NULL));
    for (int i=0; i<N; ++i) ck(pthread_join(t[i],NULL));
    assert(count==N*R); printf("count=%d\n",count); return 0;
}
```

Why it is correct: Exactly one test-and-set can observe a clear gate before the owner clears it. Acquire/release orders protected writes between owners. Finite work is small; this TAS lock does not promise bounded waiting.

