Plan: Use empty/full permits for capacity and one mutex for insertion and removal.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
static void ck(int e) { if (e) { fprintf(stderr, "pthread error %d\n", e); exit(1); } }
/* Semaphore wait/signal (P/V) map to sem_wait/sem_post. */
static void P(sem_t *s) {
    while (sem_wait(s) == -1) { if (errno != EINTR) abort(); }
}
static void V(sem_t *s) { if (sem_post(s) == -1) abort(); }
static void init(sem_t *s, unsigned n) { if (sem_init(s, 0, n)) abort(); }
static void drop(sem_t *s) { if (sem_destroy(s)) abort(); }
enum { CAP=3, ITEMS=20 };
static int buf[CAP],head,tail,count,sum;
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static sem_t empty,full;
static void *producer(void *arg) {
    (void)arg;
    for (int x=1; x<=ITEMS; ++x) {
        P(&empty); ck(pthread_mutex_lock(&m)); /* entry section */
        assert(count<CAP); buf[tail]=x; tail=(tail+1)%CAP; ++count;
        ck(pthread_mutex_unlock(&m)); V(&full); /* exit + publication */
    } return NULL;
}
static void *consumer(void *arg) {
    (void)arg;
    for (int want=1; want<=ITEMS; ++want) {
        P(&full); ck(pthread_mutex_lock(&m));
        assert(count>0); int x=buf[head]; head=(head+1)%CAP; --count;
        assert(x==want); sum+=x;
        ck(pthread_mutex_unlock(&m)); V(&empty);
    } return NULL;
}
int main(void) {
    pthread_t p,c; init(&empty,CAP); init(&full,0);
    ck(pthread_create(&p,NULL,producer,NULL)); ck(pthread_create(&c,NULL,consumer,NULL));
    ck(pthread_join(p,NULL)); ck(pthread_join(c,NULL));
    assert(count==0 && sum==ITEMS*(ITEMS+1)/2);
    printf("items=%d sum=%d\n",ITEMS,sum);
    drop(&empty); drop(&full); ck(pthread_mutex_destroy(&m)); return 0;
}
```

Why it is correct: P(empty) and P(full) occur before locking m, so a capacity wait cannot trap the counterpart behind m. Items are published only after insertion. The consumer asserts each expected FIFO value.

