Plan: Retry a weak CAS with its updated expected value until that increment succeeds.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
static void ck(int e) { if (e) { fprintf(stderr, "pthread error %d\n", e); exit(1); } }
enum { N=3, R=33 };
static atomic_int count;
static void *worker(void *arg) {
    (void)arg;
    for (int k=0; k<R; ++k) {
        int old=atomic_load(&count);
        while (!atomic_compare_exchange_weak(&count,&old,old+1)) {}
    } return NULL;
}
int main(void) {
    pthread_t t[N]; atomic_init(&count,0);
    for (int i=0; i<N; ++i) ck(pthread_create(&t[i],NULL,worker,NULL));
    for (int i=0; i<N; ++i) ck(pthread_join(t[i],NULL));
    int result=atomic_load(&count); assert(result==N*R);
    printf("count=%d\n",result); return 0;
}
```

Why it is correct: Every successful CAS contributes exactly one increment. Failure updates old or may be spurious, so the while loop retries and recalculates old+1. Joins establish completion. Mutex-free source does not imply that atomic_int is lock-free on every platform.

