Plan: Acquire the lower-numbered fork first, including at the ring wraparound.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
static void ck(int e) { if (e) { fprintf(stderr, "pthread error %d\n", e); exit(1); } }
enum { N=4, MEALS=3 };
static pthread_mutex_t fork_m[N];
static int ids[N],eaten[N];
static void *diner(void *arg) {
    int id=*(int *)arg,a=id,b=(id+1)%N;
    int low=a<b?a:b,high=a<b?b:a;
    for (int k=0; k<MEALS; ++k) {
        ck(pthread_mutex_lock(&fork_m[low]));
        ck(pthread_mutex_lock(&fork_m[high])); /* entry section */
        ++eaten[id]; /* both forks held */
        ck(pthread_mutex_unlock(&fork_m[high]));
        ck(pthread_mutex_unlock(&fork_m[low])); /* exit section */
    } return NULL;
}
int main(void) {
    pthread_t t[N]; int total=0;
    for (int i=0; i<N; ++i) { ids[i]=i; ck(pthread_mutex_init(&fork_m[i],NULL)); }
    for (int i=0; i<N; ++i) ck(pthread_create(&t[i],NULL,diner,&ids[i]));
    for (int i=0; i<N; ++i) { ck(pthread_join(t[i],NULL)); assert(eaten[i]==MEALS); total+=eaten[i]; }
    printf("meals=%d\n",total);
    for (int i=0; i<N; ++i) ck(pthread_mutex_destroy(&fork_m[i]));
    return 0;
}
```

Why it is correct: Every acquisition follows one increasing resource order, preventing circular wait. Each fork has one mutex owner. Each eaten element has one worker writer and is read only after that worker is joined. This finite demonstration does not promise fairness under infinite demand.

