static void ck(int e) { if (e) { fprintf(stderr, "pthread error %d\n", e); exit(1); } }
enum { READERS=4, R=46 };
static pthread_rwlock_t rw=PTHREAD_RWLOCK_INITIALIZER;
static int value,twice;
static void *reader(void *arg) {
    (void)arg;
    for (int i=0; i<R; ++i) {
        ck(pthread_rwlock_rdlock(&rw));
        assert(twice==2*value);
        ck(pthread_rwlock_unlock(&rw));
    } return NULL;
}
static void *writer(void *arg) {
    (void)arg;
    for (int i=0; i<R; ++i) {
        ck(pthread_rwlock_wrlock(&rw)); ++value; twice=2*value;
        ck(pthread_rwlock_unlock(&rw));
    } return NULL;
}
int main(void) {
    pthread_t t[READERS+1];
    for (int i=0; i<READERS; ++i) ck(pthread_create(&t[i],NULL,reader,NULL));
    ck(pthread_create(&t[READERS],NULL,writer,NULL));
    for (int i=0; i<=READERS; ++i) ck(pthread_join(t[i],NULL));
    assert(value==R && twice==2*R); printf("value=%d twice=%d\n",value,twice);
    ck(pthread_rwlock_destroy(&rw)); return 0;
}
```

Why it is correct: Writers exclude all readers while both fields change; readers can coexist because they only read. All accesses follow one rwlock protocol. This finite example does not claim a universal fairness policy.

