Plan: Serialize reader-count transitions and let the first/last reader acquire/release resource.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
static void ck(int e) { if (e) { fprintf(stderr, "pthread error %d\n", e); exit(1); } }
/* Semaphore wait/signal (P/V) map to sem_wait/sem_post. */
static void P(sem_t *s) {
    while (sem_wait(s) == -1) { if (errno != EINTR) abort(); }
}
static void V(sem_t *s) { if (sem_post(s) == -1) abort(); }
static void init(sem_t *s, unsigned n) { if (sem_init(s, 0, n)) abort(); }
static void drop(sem_t *s) { if (sem_destroy(s)) abort(); }
enum { READERS=4, R=46 };
static sem_t resource;
static pthread_mutex_t rc_m=PTHREAD_MUTEX_INITIALIZER;
static int rc,value;
static void *reader(void *arg) {
    (void)arg;
    for (int i=0; i<R; ++i) {
        ck(pthread_mutex_lock(&rc_m));
        if (++rc==1) P(&resource);
        ck(pthread_mutex_unlock(&rc_m));
        assert(value>=0 && value<=R); /* reader critical section */
        ck(pthread_mutex_lock(&rc_m));
        if (--rc==0) V(&resource);
        ck(pthread_mutex_unlock(&rc_m));
    } return NULL;
}
static void *writer(void *arg) {
    (void)arg;
    for (int i=0; i<R; ++i) { P(&resource); ++value; V(&resource); }
    return NULL;
}
int main(void) {
    pthread_t t[READERS+1]; init(&resource,1);
    for (int i=0; i<READERS; ++i) ck(pthread_create(&t[i],NULL,reader,NULL));
    ck(pthread_create(&t[READERS],NULL,writer,NULL));
    for (int i=0; i<=READERS; ++i) ck(pthread_join(t[i],NULL));
    assert(rc==0 && value==R); printf("value=%d readers=%d\n",value,READERS);
    drop(&resource); ck(pthread_mutex_destroy(&rc_m)); return 0;
}
```

Why it is correct: rc_m protects the first/last-reader decisions. The resource permit excludes the writer from every active reader cohort. Holding rc_m while the first reader waits is safe here because the writer never needs rc_m. Infinite reader arrivals could starve writers; these readers finish finite work.

