Plan: Protect a bounded waiting queue, announce arrivals with P/V, and close after all customers finish.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
static void ck(int e) { if (e) { fprintf(stderr, "pthread error %d\n", e); exit(1); } }
/* Semaphore wait/signal (P/V) map to sem_wait/sem_post. */
static void P(sem_t *s) {
    while (sem_wait(s) == -1) { if (errno != EINTR) abort(); }
}
static void V(sem_t *s) { if (sem_post(s) == -1) abort(); }
static void init(sem_t *s, unsigned n) { if (sem_init(s, 0, n)) abort(); }
static void drop(sem_t *s) { if (sem_destroy(s)) abort(); }
enum { CHAIRS=3, N=6 };
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static sem_t arrivals,done[N];
static int queue[CHAIRS],head,tail,waiting,closed,served,rejected,ids[N];
static void *customer(void *arg) {
    int id=*(int *)arg;
    ck(pthread_mutex_lock(&m));
    if (waiting==CHAIRS) { ++rejected; ck(pthread_mutex_unlock(&m)); return NULL; }
    queue[tail]=id; tail=(tail+1)%CHAIRS; ++waiting;
    ck(pthread_mutex_unlock(&m)); V(&arrivals);
    P(&done[id]); return NULL;
}
static void *barber(void *arg) {
    (void)arg;
    for (;;) {
        P(&arrivals); ck(pthread_mutex_lock(&m));
        if (closed && waiting==0) { ck(pthread_mutex_unlock(&m)); break; }
        assert(waiting>0); int id=queue[head]; head=(head+1)%CHAIRS; --waiting;
        ck(pthread_mutex_unlock(&m));
        /* A haircut is a finite service action, with no artificial sleep. */
        ck(pthread_mutex_lock(&m)); ++served; ck(pthread_mutex_unlock(&m));
        V(&done[id]);
    } return NULL;
}
int main(void) {
    pthread_t b,t[N]; init(&arrivals,0);
    for (int i=0; i<N; ++i) { ids[i]=i; init(&done[i],0); }
    ck(pthread_create(&b,NULL,barber,NULL));
    for (int i=0; i<N; ++i) ck(pthread_create(&t[i],NULL,customer,&ids[i]));
    for (int i=0; i<N; ++i) ck(pthread_join(t[i],NULL));
    ck(pthread_mutex_lock(&m)); closed=1; ck(pthread_mutex_unlock(&m)); V(&arrivals);
    ck(pthread_join(b,NULL)); assert(served+rejected==N && waiting==0);
    printf("customers=%d accounted=%d\n",N,served+rejected);
    for (int i=0; i<N; ++i) drop(&done[i]);
    drop(&arrivals); ck(pthread_mutex_destroy(&m)); return 0;
}
```

Why it is correct: The room mutex protects occupancy and IDs. Each accepted customer waits on its own completion semaphore, so service is matched correctly. Customers that find every chair occupied leave. After all joins, a closure post wakes the barber, then it is joined before destruction.

