Plan: Protect queue state with m, wait on predicates in while loops, and broadcast durable closure.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
static void ck(int e) { if (e) { fprintf(stderr, "pthread error %d\n", e); exit(1); } }
enum { CAP=6, ITEMS=41 };
static int buf[CAP],head,tail,count,closed,sum;
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t ne=PTHREAD_COND_INITIALIZER,nf=PTHREAD_COND_INITIALIZER;
static void *producer(void *arg) {
    (void)arg;
    for (int x=1; x<=ITEMS; ++x) {
        ck(pthread_mutex_lock(&m)); /* entry section */
        while (count==CAP) ck(pthread_cond_wait(&nf,&m));
        buf[tail]=x; tail=(tail+1)%CAP; ++count; /* critical section */
        ck(pthread_cond_signal(&ne)); ck(pthread_mutex_unlock(&m));
    }
    ck(pthread_mutex_lock(&m)); closed=1;
    ck(pthread_cond_broadcast(&ne)); ck(pthread_mutex_unlock(&m));
    return NULL;
}
static void *consumer(void *arg) {
    (void)arg; int want=1;
    for (;;) {
        ck(pthread_mutex_lock(&m));
        while (count==0 && !closed) ck(pthread_cond_wait(&ne,&m));
        if (count==0 && closed) { ck(pthread_mutex_unlock(&m)); break; }
        int x=buf[head]; head=(head+1)%CAP; --count;
        assert(x==want++); sum+=x;
        ck(pthread_cond_signal(&nf)); ck(pthread_mutex_unlock(&m)); /* exit */
    }
    assert(want==ITEMS+1); return NULL;
}
int main(void) {
    pthread_t p,c;
    ck(pthread_create(&p,NULL,producer,NULL)); ck(pthread_create(&c,NULL,consumer,NULL));
    ck(pthread_join(p,NULL)); ck(pthread_join(c,NULL));
    assert(count==0 && sum==ITEMS*(ITEMS+1)/2);
    printf("items=%d sum=%d\n",ITEMS,sum);
    ck(pthread_cond_destroy(&ne)); ck(pthread_cond_destroy(&nf));
    ck(pthread_mutex_destroy(&m)); return 0;
}
```

Why it is correct: Wait atomically releases m and reacquires it. While loops handle spurious wakeups and closure; an empty closed queue ends consumption, while pending items still drain.

