Plan: Store whose turn it is under m and notify after each handoff.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
static void ck(int e) { if (e) { fprintf(stderr, "pthread error %d\n", e); exit(1); } }
enum { R=7 };
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t changed=PTHREAD_COND_INITIALIZER;
static int turn,count,ids[2]={0,1};
static void *worker(void *arg) {
    int id=*(int *)arg;
    for (int i=0; i<R; ++i) {
        ck(pthread_mutex_lock(&m));
        while (turn!=id) ck(pthread_cond_wait(&changed,&m));
        assert(count%2==id); ++count; turn=1-id;
        ck(pthread_cond_broadcast(&changed)); ck(pthread_mutex_unlock(&m));
    } return NULL;
}
int main(void) {
    pthread_t t[2];
    for (int i=0; i<2; ++i) ck(pthread_create(&t[i],NULL,worker,&ids[i]));
    for (int i=0; i<2; ++i) ck(pthread_join(t[i],NULL));
    assert(count==2*R); printf("alternations=%d\n",count);
    ck(pthread_cond_destroy(&changed)); ck(pthread_mutex_destroy(&m)); return 0;
}
```

Why it is correct: The critical section tests and updates turn under one mutex. A while predicate guards every wait; both workers have the same finite turn count, so neither leaves the peer waiting for an extra turn.

