Plan: Use two atomic intention flags and an atomic turn, with their default sequentially consistent ordering.

```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>
#include <errno.h>
static void ck(int e) { if (e) { fprintf(stderr, "pthread error %d\n", e); exit(1); } }
enum { R=72 };
static atomic_int flag[2],turn;
static int count,ids[2]={0,1};
static void *worker(void *arg) {
    int i=*(int *)arg,j=1-i;
    for (int k=0; k<R; ++k) {
        atomic_store(&flag[i],1); atomic_store(&turn,j); /* entry section */
        while (atomic_load(&flag[j]) && atomic_load(&turn)==j) {}
        ++count; /* critical section */
        atomic_store(&flag[i],0); /* exit section */
    } return NULL;
}
int main(void) {
    pthread_t t[2]; atomic_init(&flag[0],0); atomic_init(&flag[1],0); atomic_init(&turn,0);
    for (int i=0; i<2; ++i) ck(pthread_create(&t[i],NULL,worker,&ids[i]));
    for (int i=0; i<2; ++i) ck(pthread_join(t[i],NULL));
    assert(count==2*R); printf("count=%d\n",count); return 0;
}
```

Why it is correct: Peterson excludes simultaneous entry under sequential consistency. Each ordinary count access is inside that protocol, and the exit section clears interest. Joins precede the final read; termination assumes both contenders keep being scheduled.

