question:
Is this shared-counter program correct when each worker increments 4 times? Assume successful API calls unless the ownership protocol itself is invalid.
```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <assert.h>
#include <stdio.h>
static int count;
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static void *worker(void *arg) {
    (void)arg;
    for (int i=0;i<4;++i) ++count;
    return NULL;
}
int main(void) {
    pthread_t a,b;
    pthread_create(&a,NULL,worker,NULL); pthread_create(&b,NULL,worker,NULL);
    pthread_join(a,NULL); pthread_join(b,NULL);
    printf("%d\n",count); pthread_mutex_destroy(&m); return 0;
}
```

answer:
Verdict: bug found

Line 11: `for (int i=0;i<4;++i) ++count;`

The mutex is declared but never used. Concurrent ordinary read-modify-write accesses to count are a C data race.

The table is an idealized load/store failure illustration; actual raced C has undefined behavior, not a guaranteed final count.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | read count for first increment |  | modeled count=0, localA=0 |
| 2 |  | read count for first increment | modeled count=0, localB=0 |
| 3 | store localA+1 |  | modeled count=1 |
| 4 |  | store localB+1 | modeled count=1; one update lost |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -8,7 +8,11 @@
 static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
 static void *worker(void *arg) {
     (void)arg;
-    for (int i=0;i<4;++i) ++count;
+    for (int i=0;i<4;++i) {
+        pthread_mutex_lock(&m);
+        ++count;
+        pthread_mutex_unlock(&m);
+    }
     return NULL;
 }
 int main(void) {
```

The entry section locks the same m in both workers; the exit section unlocks after the whole increment. Joins then make the final read occur after both finite loops.

question:
Why can this one-operation buffer protocol hang with 1 initially present items and no empty slots? Focus on semaphore order; item movement is omitted. Assume successful API calls unless the ownership protocol itself is invalid.
```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <assert.h>
#include <stdio.h>
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static sem_t empty,full;
static void *producer(void *arg) {
    (void)arg;
    pthread_mutex_lock(&m);
    sem_wait(&empty);
    pthread_mutex_unlock(&m); sem_post(&full); return NULL;
}
static void *consumer(void *arg) {
    (void)arg;
    sem_wait(&full); pthread_mutex_lock(&m);
    /* remove one initially present item */
    pthread_mutex_unlock(&m); sem_post(&empty); return NULL;
}
int main(void) {
    pthread_t a,b; sem_init(&empty,0,0); sem_init(&full,0,1);
    pthread_create(&a,NULL,producer,NULL); pthread_create(&b,NULL,consumer,NULL);
    pthread_join(a,NULL); pthread_join(b,NULL);
    sem_destroy(&empty); sem_destroy(&full); pthread_mutex_destroy(&m); return 0;
}
```

answer:
Verdict: bug found

Line 11: `pthread_mutex_lock(&m);`
Line 12: `sem_wait(&empty);`

The producer waits for space while holding the mutex needed by the consumer to free space.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | lock(m) succeeds |  | m=A, empty=0, full=1 |
| 2 | sem_wait(empty) blocks |  | A owns m |
| 3 |  | sem_wait(full) succeeds | full=0, A owns m |
| 4 |  | lock(m) blocks | cycle: A needs B to create space; B needs A's m |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -8,8 +8,8 @@
 static sem_t empty,full;
 static void *producer(void *arg) {
     (void)arg;
+    sem_wait(&empty);
     pthread_mutex_lock(&m);
-    sem_wait(&empty);
     pthread_mutex_unlock(&m); sem_post(&full); return NULL;
 }
 static void *consumer(void *arg) {
```

Semaphore wait(P), sem_wait(empty), now occurs before the entry mutex acquisition. The consumer can reach its exit section and signal(V), sem_post(empty).

question:
Could this completion-notification program hang even after ready becomes 4? Is its unconditional wait correct? Assume successful API calls unless the ownership protocol itself is invalid.
```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <assert.h>
#include <stdio.h>
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int ready;
static void *producer(void *arg) {
    (void)arg; pthread_mutex_lock(&m); ready=4;
    pthread_cond_signal(&cv); pthread_mutex_unlock(&m); return NULL;
}
static void *consumer(void *arg) {
    (void)arg; pthread_mutex_lock(&m);
    pthread_cond_wait(&cv,&m);
    assert(ready==4); pthread_mutex_unlock(&m); return NULL;
}
int main(void) {
    pthread_t a,b; pthread_create(&b,NULL,producer,NULL); pthread_create(&a,NULL,consumer,NULL);
    pthread_join(a,NULL); pthread_join(b,NULL);
    pthread_cond_destroy(&cv); pthread_mutex_destroy(&m); return 0;
}
```

answer:
Verdict: bug found

Line 16: `pthread_cond_wait(&cv,&m);`

The consumer waits without first testing durable state. A producer that finishes first has already signaled an empty wait set.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 |  | lock(m) succeeds | m=B, ready=0 |
| 2 |  | ready = 4 | m=B, ready=4 |
| 3 |  | signal(cv) | no waiter; notification not saved |
| 4 |  | unlock(m) | m=free |
| 5 | lock(m) succeeds |  | m=A, ready=4 |
| 6 | cond_wait: release-and-wait |  | A waits despite completed work; no future signal |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -13,7 +13,7 @@
 }
 static void *consumer(void *arg) {
     (void)arg; pthread_mutex_lock(&m);
-    pthread_cond_wait(&cv,&m);
+    while (ready==0) pthread_cond_wait(&cv,&m);
     assert(ready==4); pthread_mutex_unlock(&m); return NULL;
 }
 int main(void) {
```

Testing ready under m and waiting only while it is zero handles both signal-before-wait and spurious wakeups. The existing predicate update is already protected.

question:
Is an if check sufficient before this condition wait for ready==4? Consider an allowed spurious wakeup. Assume successful API calls unless the ownership protocol itself is invalid.
```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <assert.h>
#include <stdio.h>
static pthread_mutex_t m=PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv=PTHREAD_COND_INITIALIZER;
static int ready;
static void *consumer(void *arg) {
    (void)arg; pthread_mutex_lock(&m);
    if (ready==0) pthread_cond_wait(&cv,&m);
    assert(ready==4); pthread_mutex_unlock(&m); return NULL;
}
static void *producer(void *arg) {
    (void)arg; pthread_mutex_lock(&m); ready=4;
    pthread_cond_signal(&cv); pthread_mutex_unlock(&m); return NULL;
}
int main(void) {
    pthread_t a,b; pthread_create(&a,NULL,consumer,NULL); pthread_create(&b,NULL,producer,NULL);
    pthread_join(a,NULL); pthread_join(b,NULL);
