 static void *worker(void *arg) {
     (void)arg;
-    pthread_mutex_unlock(&m);
+    pthread_mutex_lock(&m);
     count += 10;
     pthread_mutex_unlock(&m); return NULL;
 }
```

Replace the entry unlock with lock. The worker then owns m for the update and executes exactly one matching unlock in its exit section.

question:
Why does this normal-mutex program never finish its intended count += 10? Assume successful API calls unless the ownership protocol itself is invalid.
```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <assert.h>
#include <stdio.h>
static pthread_mutex_t m;
static int count;
static void *worker(void *arg) {
    (void)arg;
    pthread_mutex_lock(&m);
    pthread_mutex_lock(&m);
    count += 10;
    pthread_mutex_unlock(&m); return NULL;
}
int main(void) {
    pthread_mutexattr_t attr; pthread_t a;
    pthread_mutexattr_init(&attr); pthread_mutexattr_settype(&attr,PTHREAD_MUTEX_NORMAL);
    pthread_mutex_init(&m,&attr); pthread_mutexattr_destroy(&attr);
