answer:
Verdict: bug found

Line 11: `printf("result=%d\n",result);`

Main reads result without a completion edge and may exit before the worker finishes. A conflicting overlapping worker write also has no required happens-before ordering.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | worker not scheduled yet |  | result=0 |
| 2 |  | main reads result for printf | no completion ordering |
| 3 |  | main returns from main | process can exit before worker writes |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -8,6 +8,7 @@
 static void *worker(void *arg) { (void)arg; result=10; return NULL; }
 int main(void) {
     pthread_t a; pthread_create(&a,NULL,worker,NULL);
+    pthread_join(a,NULL);
     printf("result=%d\n",result);
     return 0;
 }
```

Join the successfully created worker before reading result. Join waits for completion and orders its writes before the main-thread observation.

question:
Is this two-lock update program deadlock-free if both workers add 10 to result? Assume successful API calls unless the ownership protocol itself is invalid.
```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <assert.h>
#include <stdio.h>
static pthread_mutex_t l=PTHREAD_MUTEX_INITIALIZER,r=PTHREAD_MUTEX_INITIALIZER;
static int result;
static void *a_worker(void *arg) {
    (void)arg; pthread_mutex_lock(&l); pthread_mutex_lock(&r);
    result += 10; pthread_mutex_unlock(&r); pthread_mutex_unlock(&l); return NULL;
}
static void *b_worker(void *arg) {
    (void)arg; pthread_mutex_lock(&r); pthread_mutex_lock(&l);
    result += 10; pthread_mutex_unlock(&l); pthread_mutex_unlock(&r); return NULL;
}
int main(void) {
    pthread_t a,b; pthread_create(&a,NULL,a_worker,NULL); pthread_create(&b,NULL,b_worker,NULL);
    pthread_join(a,NULL); pthread_join(b,NULL); printf("%d\n",result);
    pthread_mutex_destroy(&l); pthread_mutex_destroy(&r); return 0;
}
```

answer:
Verdict: bug found

Line 14: `(void)arg; pthread_mutex_lock(&r); pthread_mutex_lock(&l);`

The two entry sections acquire the same exclusive resources in opposite orders.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | lock(l) succeeds |  | l=A, r=free |
| 2 |  | lock(r) succeeds | l=A, r=B |
| 3 | lock(r) blocks |  | A waits for B |
| 4 |  | lock(l) blocks | B waits for A; circular wait |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -11,8 +11,8 @@
     result += 10; pthread_mutex_unlock(&r); pthread_mutex_unlock(&l); return NULL;
 }
 static void *b_worker(void *arg) {
-    (void)arg; pthread_mutex_lock(&r); pthread_mutex_lock(&l);
-    result += 10; pthread_mutex_unlock(&l); pthread_mutex_unlock(&r); return NULL;
+    (void)arg; pthread_mutex_lock(&l); pthread_mutex_lock(&r);
+    result += 10; pthread_mutex_unlock(&r); pthread_mutex_unlock(&l); return NULL;
 }
 int main(void) {
     pthread_t a,b; pthread_create(&a,NULL,a_worker,NULL); pthread_create(&b,NULL,b_worker,NULL);
```

Both entry sections now acquire l then r and exit in reverse order. Increasing acquisition order removes circular wait while still protecting result.

question:
Is this plain-flag spin wait a portable way to publish payload 10? Would adding volatile be enough? Assume successful API calls unless the ownership protocol itself is invalid.
```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <assert.h>
#include <stdio.h>
static int ready,payload;
static void *producer(void *arg) { (void)arg; payload=10; ready=1; return NULL; }
static void *consumer(void *arg) {
    (void)arg;
    while (!ready) {}
    assert(payload==10); return NULL;
}
int main(void) {
    pthread_t a,b; pthread_create(&a,NULL,consumer,NULL); pthread_create(&b,NULL,producer,NULL);
    pthread_join(a,NULL); pthread_join(b,NULL); return 0;
}
```

answer:
Verdict: bug found

Line 7: `static int ready,payload;`
Line 8: `static void *producer(void *arg) { (void)arg; payload=10; ready=1; return NULL; }`
Line 11: `while (!ready) {}`

The flag has a C data race, and the payload lacks a safe publication edge. Neither an ordinary polling loop nor volatile supplies the needed protocol.

The table identifies conflicting operations; it does not predict one deterministic outcome for undefined raced C behavior.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | read plain ready -> 0 |  | no synchronization edge |
| 2 |  | write payload=10 | payload=10; unpublished |
| 3 |  | write plain ready=1 | conflicts with A's unsynchronized reads |
| 4 | continue ordinary ready polling |  | C data race; no valid visibility or termination guarantee |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -4,11 +4,12 @@
 #include <stdatomic.h>
 #include <assert.h>
 #include <stdio.h>
-static int ready,payload;
-static void *producer(void *arg) { (void)arg; payload=10; ready=1; return NULL; }
+static atomic_int ready;
+static int payload;
+static void *producer(void *arg) { (void)arg; payload=10; atomic_store_explicit(&ready,1,memory_order_release); return NULL; }
 static void *consumer(void *arg) {
     (void)arg;
-    while (!ready) {}
+    while (!atomic_load_explicit(&ready,memory_order_acquire)) {}
     assert(payload==10); return NULL;
 }
 int main(void) {
```

An atomic release store of ready publishes the preceding payload write. An acquire load observing 1 orders the payload read afterward; the spin loop assumes the producer is scheduled.

question:
Why does this semaphore-as-mutex example hang before either 10-unit update? Assume successful API calls unless the ownership protocol itself is invalid.
```c
