#include <stdatomic.h>
#include <assert.h>
#include <stdio.h>
static sem_t gate;
static int count;
static void *worker(void *arg) {
    (void)arg; sem_wait(&gate); count += 10; sem_post(&gate); return NULL;
}
int main(void) {
    pthread_t a,b; sem_init(&gate,0,0);
    pthread_create(&a,NULL,worker,NULL); pthread_create(&b,NULL,worker,NULL);
