     (void)arg; pthread_mutex_lock(&m);
-    pthread_cond_wait(&cv,&m);
+    while (ready==0) pthread_cond_wait(&cv,&m);
     assert(ready==16); pthread_mutex_unlock(&m); return NULL;
 }
 int main(void) {
```

Testing ready under m and waiting only while it is zero handles both signal-before-wait and spurious wakeups. The existing predicate update is already protected.

