     (void)arg; pthread_mutex_lock(&m);
-    if (ready==0) pthread_cond_wait(&cv,&m);
+    while (ready==0) pthread_cond_wait(&cv,&m);
     assert(ready==16); pthread_mutex_unlock(&m); return NULL;
 }
