question:
Is this two-lock update program deadlock-free if both workers add 16 to result? Assume successful API calls unless the ownership protocol itself is invalid.
```c
#define _XOPEN_SOURCE 700
#include <pthread.h>
#include <semaphore.h>
#include <stdatomic.h>
#include <assert.h>
#include <stdio.h>
static pthread_mutex_t l=PTHREAD_MUTEX_INITIALIZER,r=PTHREAD_MUTEX_INITIALIZER;
static int result;
static void *a_worker(void *arg) {
    (void)arg; pthread_mutex_lock(&l); pthread_mutex_lock(&r);
    result += 16; pthread_mutex_unlock(&r); pthread_mutex_unlock(&l); return NULL;
}
static void *b_worker(void *arg) {
    (void)arg; pthread_mutex_lock(&r); pthread_mutex_lock(&l);
    result += 16; pthread_mutex_unlock(&l); pthread_mutex_unlock(&r); return NULL;
}
int main(void) {
    pthread_t a,b; pthread_create(&a,NULL,a_worker,NULL); pthread_create(&b,NULL,b_worker,NULL);
    pthread_join(a,NULL); pthread_join(b,NULL); printf("%d\n",result);
    pthread_mutex_destroy(&l); pthread_mutex_destroy(&r); return 0;
}
```

answer:
Verdict: bug found

Line 14: `(void)arg; pthread_mutex_lock(&r); pthread_mutex_lock(&l);`

The two entry sections acquire the same exclusive resources in opposite orders.

| Step | Thread A | Thread B | Shared state |
|---|---|---|---|
| 1 | lock(l) succeeds |  | l=A, r=free |
| 2 |  | lock(r) succeeds | l=A, r=B |
| 3 | lock(r) blocks |  | A waits for B |
| 4 |  | lock(l) blocks | B waits for A; circular wait |

Fix:
```diff
--- prog.c
+++ prog.c (fixed)
@@ -11,8 +11,8 @@
     result += 16; pthread_mutex_unlock(&r); pthread_mutex_unlock(&l); return NULL;
 }
 static void *b_worker(void *arg) {
-    (void)arg; pthread_mutex_lock(&r); pthread_mutex_lock(&l);
-    result += 16; pthread_mutex_unlock(&l); pthread_mutex_unlock(&r); return NULL;
+    (void)arg; pthread_mutex_lock(&l); pthread_mutex_lock(&r);
+    result += 16; pthread_mutex_unlock(&r); pthread_mutex_unlock(&l); return NULL;
 }
 int main(void) {
     pthread_t a,b; pthread_create(&a,NULL,a_worker,NULL); pthread_create(&b,NULL,b_worker,NULL);
```

Both entry sections now acquire l then r and exit in reverse order. Increasing acquisition order removes circular wait while still protecting result.

question:
Is this plain-flag spin wait a portable way to publish payload 16? Would adding volatile be enough? Assume successful API calls unless the ownership protocol itself is invalid.
```c
#define _XOPEN_SOURCE 700
