#include <semaphore.h>
#include <stdatomic.h>
#include <assert.h>
#include <stdio.h>
static pthread_mutex_t l=PTHREAD_MUTEX_INITIALIZER,r=PTHREAD_MUTEX_INITIALIZER;
static int count;
static void *worker(void *arg) {
    (void)arg; pthread_mutex_lock(&l); pthread_mutex_lock(&r);
    count+=16; pthread_mutex_unlock(&r); pthread_mutex_unlock(&l); return NULL;
}
int main(void) {
    pthread_t a,b; pthread_create(&a,NULL,worker,NULL); pthread_create(&b,NULL,worker,NULL);
    pthread_join(a,NULL); pthread_join(b,NULL); assert(count==32);
    pthread_mutex_destroy(&l); pthread_mutex_destroy(&r); return 0;
}
